/* js/core/platform-i18n.js */
/* 1GP language loader. The bundled Chinese catalog remains usable offline.
 * Legacy dynamic phrases are resolved to stable keys at the rendering boundary.
 * New UI must call G.t(key, parameters); save data uses IDs, never rendered text.
 */
G.Text = (() => {
  const original = G.TextOriginal;
  let translate = (key, vars) => format(original[key] ?? key, vars);
  const format = (text, vars) => vars ? String(text).replace(/\{(\w+)\}/g, (all, k) => Object.hasOwn(vars, k) ? String(vars[k]) : all) : String(text);
  function t(key, vars) {
    const species = /^pokemon\.(\d+)$/.exec(key);
    if (species) {
      const index = Number(species[1]) - 1;
      return translate('pokemon.group.' + Math.floor(index / 10)).split(' | ')[index % 10];
    }
    return translate(key, vars);
  }
  function sdk() {
    if (window.AIMadeGames?.i18n) return Promise.resolve(window.AIMadeGames);
    return new Promise(resolve => {
      const script = document.createElement('script');
      script.src = 'https://www.ai-made.games/sdk/v1.js';
      script.onload = () => resolve(window.AIMadeGames);
      script.onerror = () => resolve(null);
      document.head.appendChild(script);
      setTimeout(() => resolve(window.AIMadeGames || null), 4500);
    });
  }
  async function init() {
    const api = await sdk();
    const lang = G.I18n.lang === 'zh-CN' ? 'zh' : G.I18n.lang;
    if (api?.i18n) {
      try {
        translate = await api.i18n({ game: 'game-a5098b633e484a4f', original, originalLang: 'zh', lang, timeout: 4000 });
      } catch (_) { /* Keep the bundled original catalog available offline. */ }
    }
    const dict = {};
    for (const key of Object.keys(original)) dict[key] = t(key);
    for (const [source, key] of Object.entries(G.TextAliases)) {
      dict[source] = t(key).replace(/\{\d+\}/g, '{x}');
    }
    // Names and gameplay IDs are separate; a language change never changes dex IDs.
    for (const mon of G.DEX) {
      const key = 'pokemon.' + mon.dex;
      if (mon.dex >= 1 && mon.dex <= 1025) mon.name = t(key);
    }
    G.I18n.add(dict);
    document.title = t('meta.title');
    document.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = t(el.dataset.i18n); });
    const font = { zh: 'NotoSC', ja: 'NotoJP', ko: 'NotoKR' }[lang];
    if (font && document.fonts?.load) await document.fonts.load('16px ' + font).catch(() => {});
  }
  return { t, init, original };
})();
G.t = G.Text.t;

;

/* js/core/settings.js */
/* ============ settings.js — ajustes de este dispositivo ============
 * Se guardan en el navegador (no en la cuenta): cada PC o móvil tiene los
 * suyos. El volumen lo guarda audio.js aparte.
 *
 *   quality     'auto' | 'high' | 'mid' | 'low'   efectos y partículas
 *   dmgNumbers  true/false                        números de daño
 *   calm        true/false                        menos sacudidas y destellos
 *   fps         true/false                        contador de FPS
 *   stick       0.8 | 1 | 1.25                    tamaño del joystick táctil
 *   stickMode   'float' | 'fixed'                 joystick donde pones el dedo, o siempre en su sitio
 *   pad         { bar, pause, stick } | null      dónde van los botones en móvil (centro, en
 *                                                 proporción a la pantalla); lo pone layout-ui.js
 *
 *   G.Settings.get('quality')  ·  G.Settings.set('fps', true)  ·  G.Settings.on(fn)
 *   G.Settings.fx   nivel efectivo 0 (bajo) .. 2 (alto), ya resuelto el 'auto'
 */
G.Settings = (() => {
  const KEY = 'ps.settings';
  const DEF = { quality: 'auto', dmgNumbers: true, calm: false, fps: false, stick: 1, stickMode: 'float', pad: null };
  let s = Object.assign({}, DEF);
  try { Object.assign(s, JSON.parse(localStorage.getItem(KEY) || '{}')); } catch (e) { /* nada */ }
  const fns = new Set();

  // Calidad automática: empieza alta (media en móvil) y baja si va a tirones.
  const touchy = matchMedia('(pointer: coarse)').matches;
  let autoLevel = touchy ? 1 : 2;
  let acc = 0, frames = 0, slowT = 0, fastT = 0;

  function save() { try { localStorage.setItem(KEY, JSON.stringify(s)); } catch (e) { /* nada */ } }
  function get(k) { return s[k]; }
  function set(k, v) { s[k] = v; save(); fns.forEach(fn => { try { fn(k, v); } catch (e) { /* nada */ } }); }

  /** Lo llama el bucle del juego en cada fotograma (sólo durante la partida). */
  function sample(dt) {
    if (s.quality !== 'auto' || dt <= 0) return;
    acc += dt; frames++;
    if (acc < 1) return;
    const fps = frames / acc;
    acc = 0; frames = 0;
    // 3 s seguidos por debajo de 45 FPS: baja un nivel; 8 s por encima de 57: sube.
    if (fps < 45) { slowT++; fastT = 0; } else if (fps > 57) { fastT++; slowT = 0; } else { slowT = fastT = 0; }
    if (slowT >= 3 && autoLevel > 0) { autoLevel--; slowT = 0; }
    if (fastT >= 8 && autoLevel < (touchy ? 1 : 2)) { autoLevel++; fastT = 0; }
  }

  return {
    get, set, sample, DEF,
    on(fn) { fns.add(fn); },
    get all() { return Object.assign({}, s); },
    get fx() { return s.quality === 'auto' ? autoLevel : s.quality === 'high' ? 2 : s.quality === 'mid' ? 1 : 0; },
    get autoLevel() { return autoLevel; },
    get touch() { return touchy; }
  };
})();

;

